import React, { useEffect, useState } from "react";
import {
  Modal,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
} from "@heroui/react";

import * as Yup from "yup";
import {
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectReactSelect,
} from "../../../components";
import { useFormik } from "formik";
import useApi from "../../../hooks/useApi";
import retailersApi from "../../../api/retailers/retailersApi";
import { useStateContext } from "../../../contexts/ContextProvider";
import entitiesApi from "../../../api/entitiesApi";
import { useNavigate } from "react-router-dom";

export default function RetailerOrderPaymentFormModal({
  openPaymentMethodsModal,
  setopenPaymentMethodsModal,
  paymentMethods,
  selectedRetailerOrder,
  errors,
  setErrors,
  updated,
  setUpdated,
}) {
  const [selectedPaymentMethod, setselectedPaymentMethod] = useState();
  const [selectedOrderTerm, setselectedOrderTerm] = useState();
  const [facilitators, setFacilitators] = useState([]);
  const [selectedFacilitatorId, setselectedFacilitatorId] = useState();
  const [selectedFacilitatorTitle, setselectedFacilitatorTitle] = useState();
  const { currentColor } = useStateContext();
  const navigate = useNavigate();

  const retailerOrderPaymentApi = useApi(
    retailersApi.retailerOrdersStaffAction
  );

  const handleMakeRetailerOrderPayment = async (data) => {
    await retailerOrderPaymentApi.request(data);
  };

  const [orderTermsOptions, setorderTermsOptions] = useState([
    {
      label: "CASH",
      value: "CASH",
    },
    {
      label: "CONTRACT",
      value: "CONTRACT",
    },
    {
      label: "CREDIT",
      value: "CREDIT",
    },
    {
      label: "FACILITY",
      value: "FACILITY",
    },
    {
      label: "PLACEMENT",
      value: "PLACEMENT",
    },
  ]);

  useEffect(() => {
    console.log("retailerOrderPaymentApi.data", retailerOrderPaymentApi.data);

    if (retailerOrderPaymentApi.data) {
      if (
        retailerOrderPaymentApi.data.errors &&
        retailerOrderPaymentApi.data.errors.length
      ) {
        setErrors(retailerOrderPaymentApi.data.errors);
      } else {
        setUpdated(true);
      }
    }
  }, [retailerOrderPaymentApi.data]);

  const formik = useFormik({
    initialValues: {
      payment_method: "",
      order_terms: "",
    },

    validationSchema: Yup.object({
      payment_method: Yup.string().required().label("Payment method"),
      order_terms: Yup.string().required().label("Order terms"),
    }),
    onSubmit: (values, { resetForm }) => {
      console.log("VALZ", values);
      setopenPaymentMethodsModal(false);
      const data = {
        action: "MakeRetailerOrderPayment",
        payment_method: values.payment_method,
        retailer_order: selectedRetailerOrder.id,
        mobile_money_phone: values.mobile_money_phone,
        order_terms: values.order_terms,
      };
      console.log("data", data);
      handleMakeRetailerOrderPayment(data);
    },
  });

  const handleSelectPaymentMethod = (item) => {
    console.log("item", item);
    formik.setFieldValue("payment_method", item.value);
    setselectedPaymentMethod(item.label);
  };

  const handleSelectOrderTerms = (item) => {
    console.log("item", item);
    formik.setFieldValue("order_terms", item.value);
    setselectedOrderTerm(item.label);
  };
  const handleSelectFacilitator = (item) => {
    console.log("item", item);
    formik.setFieldValue("facilitator", item.value);
    setselectedFacilitatorId(item.value);
    setselectedFacilitatorTitle(item.label);
  };

  const facilitatorEntitiesApi = useApi(entitiesApi.entitiesAction);

  const getFacilitatorEntities = async () => {
    facilitatorEntitiesApi.request({ action: "GetFacilitatorEntities" });
  };

  useEffect(() => {
    if (facilitatorEntitiesApi.data && facilitatorEntitiesApi.data.length) {
      setFacilitators(facilitatorEntitiesApi.data.map((i) => ({ label: i.title, value: i.id })));
    }
  }, [facilitatorEntitiesApi.data]);

  useEffect(() => {
    getFacilitatorEntities();
  }, []);

  useEffect(() => {
    if (selectedOrderTerm === "FACILITY") {
      if (selectedFacilitatorId !== "" && selectedFacilitatorId !== null) {

        navigate(`/retailers/facilitators`, {
          state: {
            facilitatorId: selectedFacilitatorId,
            facilitatorTitle: selectedFacilitatorTitle,
            retalerOrderId: selectedRetailerOrder.id,
            retailerOrderAmount: selectedRetailerOrder.order_price_total,
            retailerOrderWholesalerId: selectedRetailerOrder.wholesaler,
            retailerOrderWholesalerTitle: selectedRetailerOrder.wholesaler_title,
            retailerOrderRetailerId: selectedRetailerOrder.retailer,
            retailerOrderRetailerTitle: selectedRetailerOrder.retailer_title,

          },
        });
      }
    }
  }, [selectedFacilitatorId]);  

  return (
    <>
      <Modal isOpen={openPaymentMethodsModal} placement="center">
        <ModalContent>
          {(onClose) => (
            <>
              <ModalHeader className="flex flex-col gap-1 text-center text-large font-bold">
                Select payment method
              </ModalHeader>
              <ModalBody>
                <CustomForm
                  layout="vertical"
                  handleFinish={formik.handleSubmit}
                  className=" flex flex-col justify-center items-center w-full my-7"
                >
                  <CustomFormItem
                    touched={formik.touched.order_terns}
                    error={formik.errors.order_terns}
                  >
                    <CustomSelectReactSelect
                      required={true}
                      id="order_terns"
                      name="order_terns"
                      onChange={(e) => handleSelectOrderTerms(e)}
                      placeholder="Select order terms"
                      size="large"
                      type="text"
                      options={orderTermsOptions}
                    />
                  </CustomFormItem>
                  {selectedOrderTerm === "CASH" ? (
                    <CustomFormItem
                      touched={formik.touched.payment_method}
                      error={formik.errors.payment_method}
                    >
                      <CustomSelectReactSelect
                        required={true}
                        id="payment_method"
                        name="payment_method"
                        onChange={(e) => handleSelectPaymentMethod(e)}
                        placeholder="Select payment method"
                        size="large"
                        type="text"
                        options={paymentMethods}
                      />
                    </CustomFormItem>
                  ) : (
                    <div></div>
                  )}

                  {selectedOrderTerm === "FACILITY" ? (
                    <CustomFormItem
                      touched={formik.touched.facilitator}
                      error={formik.errors.facilitator}
                    >
                      <CustomSelectReactSelect
                        required={true}
                        id="facilitator"
                        name="facilitator"
                        onChange={(e) => handleSelectFacilitator(e)}
                        placeholder="Select facilitator"
                        size="large"
                        type="text"
                        options={facilitators}
                      />
                    </CustomFormItem>
                  ) : (
                    <div></div>
                  )}

                  {selectedPaymentMethod &&
                  selectedPaymentMethod === "MOBILE MONEY" ? (
                    <CustomFormItem
                      touched={formik.touched.mobile_money_phone}
                      error={formik.errors.mobile_money_phone}
                    >
                      <CustomInput
                        required={true}
                        id="mobile_money_phone"
                        name="mobile_money_phone"
                        onChange={formik.handleChange}
                        placeholder="Enter mobile money phone"
                        size="large"
                        type="text"
                        value={formik.values.mobile_money_phone}
                        label="Enter mobile money number"
                      />
                    </CustomFormItem>
                  ) : (
                    <div></div>
                  )}
                  <div className="w-full items-center mt-2">
                    <Button
                      style={{ background: currentColor }}
                      className="w-full rounded-md self-center"
                      color="primary"
                      type="submit"
                    >
                      Confirm
                    </Button>
                  </div>
                </CustomForm>
              </ModalBody>

              <ModalFooter>
                <Button
                  color="danger"
                  variant="flat"
                  onPress={() => setopenPaymentMethodsModal(false)}
                >
                  Cancel
                </Button>
              </ModalFooter>
            </>
          )}
        </ModalContent>
      </Modal>
    </>
  );
}
